import json
from confluent_kafka import Producer

p = Producer({'bootstrap.servers': 'localhost:9092'})

def delivery_report(err, msg):
    if err is not None:
        print(f'Message delivery failed: {err}')
    else:
        print(f'Message delivered to {msg.topic()} [{msg.partition()}]')

topic = 'ingest-docs-zrany879ur'

messages = [
    {
        'key': 'doc1',
        'val': {
            'id': 'doc1',
            'text': 'The quick brown fox jumps over the lazy dog',
            'source': 'test-source',
            'ts': 1718060400
        }
    },
    {
        'key': 'doc2',
        'val': {
            'id': 'doc2',
            'text': 'Hello world from Kafka and LanceDB',
            'source': 'test-source',
            'ts': 1718060401
        }
    },
    {
        'key': 'doc1', # Duplicate key to test idempotency
        'val': {
            'id': 'doc1',
            'text': 'The quick brown fox jumps over the lazy dog - updated text',
            'source': 'test-source-updated',
            'ts': 1718060405
        }
    }
]

for m in messages:
    p.produce(
        topic,
        key=m['key'].encode('utf-8'),
        value=json.dumps(m['val']).encode('utf-8'),
        callback=delivery_report
    )

p.flush()
